function rootMessage(value: string): string { return normalized(sanitizeEvidenceText(value)).replace(/https?:\/\/\S+/g, "url").replace(/\b(?:authorization|bearer|token|secret|password|api[-_]?key|auth|credential)\s*[:=]\s*\S+/gi, "[redacted]").replace(/\b[\w.%+-]+@[\w.-]+\.[a-z]{2,}\b/gi, "email").replace(/\b\d{2,}\b/g, "#").slice(0, 180); }
