function dedupeKeyFor(draft: DiagnosticDraft): string { return `${draft.problemType}:${draft.subject.kind}:${normalized(draft.subject.key)}:${[...draft.legacyEvidenceRefs].sort().join("|")}`; }
function dedupeKeyForDetector(detectorId: string, draft: DiagnosticDraft): string { return detectorId === "broad-accessibility" ? `${draft.problemType}:${draft.subject.kind}:${normalized(draft.subject.key)}` : dedupeKeyFor(draft); }
type BroadRun = (context: DiagnosticContext, detectorId: string) => Promise<DetectorOutput>;
const BROAD_RUNS: Record<string, BroadRun> = { "broad-conversion": runConversion, "broad-accessibility": runAccessibility, "broad-consistency": runConsistency, "broad-reliability": runReliability, "broad-performance": runPerformance, "broad-freshness": runFreshness, "broad-rendered-experience": runRenderedExperience, "broad-placeholder": runPlaceholder, "broad-booking-skeleton": runBookingSkeleton };
interface BroadDefinition { detectorId: string; detectorVersion: string; category: InsightCategory; evidenceKinds: string[]; cap: number; coverage: { requiredKinds: string[]; minimumPages?: number }; dedupeKey: (draft: DiagnosticDraft) => string; run: BroadRun; }
function definition(detectorId: string, category: InsightCategory, evidenceKinds: string[], coverage: { requiredKinds: string[]; minimumPages?: number }): BroadDefinition { return { detectorId, detectorVersion: "1", category, evidenceKinds, cap: BROAD_CAP, coverage, dedupeKey: (draft) => dedupeKeyForDetector(detectorId, draft), run: BROAD_RUNS[detectorId]! }; }
export const BROAD_DETECTORS: BroadDefinition[] = [
  definition("broad-conversion", "conversion", ["element", "link", "form", "screenshot"], { requiredKinds: ["page"], minimumPages: 1 }),
  definition("broad-accessibility", "accessibility_usability", ["accessibility", "element", "form", "screenshot"], { requiredKinds: ["page"], minimumPages: 1 }),
  definition("broad-consistency", "local_market", ["contact-fact", "element", "page"], { requiredKinds: ["page"], minimumPages: 2 }),
  definition("broad-reliability", "technical_reliability", ["page", "link", "probe"], { requiredKinds: ["page"], minimumPages: 1 }),
  definition("broad-performance", "technical_reliability", ["performance", "page"], { requiredKinds: ["performance"], minimumPages: 1 }),
  definition("broad-freshness", "content_freshness", ["page", "contact-fact"], { requiredKinds: ["page"], minimumPages: 1 }),
  definition("broad-rendered-experience", "experience", ["screenshot", "element"], { requiredKinds: ["screenshot"], minimumPages: 1 }),
  definition("broad-placeholder", "content_freshness", ["page", "element"], { requiredKinds: ["page"], minimumPages: 1 }),
  definition("broad-booking-skeleton", "content_freshness", ["page", "element"], { requiredKinds: ["page"], minimumPages: 1 }),
];

function availabilityForKind(context: DiagnosticContext, availability: DiagnosticAvailability, kind: string): AvailabilityState { if (availability.unavailableEvidenceKinds?.includes(kind)) return { state: "unavailable", reason: `${kind} evidence was marked unavailable.` }; const explicit = context.evidence.evidenceAvailability?.find((entry) => entry.kind === kind); if (explicit?.state === "unavailable") return { state: "unavailable", reason: explicit.reason ?? `${kind} evidence was unavailable.` }; if (explicit?.state === "partial") return { state: "limited", reason: explicit.reason ?? `${kind} evidence was partial.` }; const pages = pagesOf(context); const present = kind === "page" ? pages.length > 0 : kind === "element" ? hasParsedElementCoverage(context, "element") || hasRenderedElementCoverage(context) : kind === "form" ? pages.some((page) => page.forms.length > 0) : kind === "accessibility" ? hasParsedElementCoverage(context, "accessibility") || hasRenderedElementCoverage(context) : kind === "contact-fact" ? pages.some((page) => page.contactFacts !== undefined) : kind === "performance" ? Boolean(context.evidence.performanceObservations?.length) : kind === "screenshot" ? Boolean(context.evidence.renderedPages?.length) : kind === "link" ? Array.isArray(context.evidence.site.links) : kind === "probe" ? typeof context.probe === "function" : false; if (!present) return { state: "unassessed", reason: `${kind} evidence was not supplied.` }; if (!context.evidence.site.crawlExhaustive && ["page", "link"].includes(kind)) return { state: "limited", reason: "The crawl was partial." }; return { state: "assessed" }; }
function detectorInputState(detector: BroadDefinition, context: DiagnosticContext, availability: DiagnosticAvailability): AvailabilityState { const states = detector.coverage.requiredKinds.map((kind) => availabilityForKind(context, availability, kind)); const unavailable = states.find((state) => state.state === "unavailable"); if (unavailable) return unavailable; if (detector.coverage.minimumPages !== undefined && pagesOf(context).length < detector.coverage.minimumPages) return { state: "unassessed", reason: `At least ${detector.coverage.minimumPages} owned evidence pages are required for this detector.` }; const unassessed = states.find((state) => state.state === "unassessed"); if (unassessed) return unassessed; const limited = states.find((state) => state.state === "limited"); return limited ?? { state: "assessed" }; }
function explicitlyEnabled(detectorId: string, availability: DiagnosticAvailability): { enabled: boolean; reason?: string } { if (availability.disabledDetectorIds?.includes(detectorId)) return { enabled: false, reason: "Detector was disabled for this run." }; if (availability.enabledDetectorIds && !availability.enabledDetectorIds.includes(detectorId)) return { enabled: false, reason: "Detector was not included in the enabled manifest." }; return { enabled: true }; }

async function executeBroadDetector(detector: BroadDefinition, context: DiagnosticContext, availability: DiagnosticAvailability): Promise<{ drafts: DiagnosticDraft[]; accounting: z.infer<typeof DetectorAccountingSchema> }> {
  const enabled = explicitlyEnabled(detector.detectorId, availability); if (!enabled.enabled) return { drafts: [], accounting: DetectorAccountingSchema.parse({ detectorId: detector.detectorId, detectorVersion: detector.detectorVersion, category: detector.category, state: "unavailable", enabled: false, emitted: 0, rejected: 0, duplicateCount: 0, capped: false, disabledReason: enabled.reason }) };
  const inputState = detectorInputState(detector, context, availability); if (inputState.state === "unavailable") return { drafts: [], accounting: DetectorAccountingSchema.parse({ detectorId: detector.detectorId, detectorVersion: detector.detectorVersion, category: detector.category, state: "unavailable", enabled: true, emitted: 0, rejected: 0, duplicateCount: 0, capped: false, limitation: inputState.reason ?? "Required evidence was unavailable." }) };
  let runOutput: DetectorOutput; try { runOutput = await detector.run(context, detector.detectorId); } catch (error) { return { drafts: [], accounting: DetectorAccountingSchema.parse({ detectorId: detector.detectorId, detectorVersion: detector.detectorVersion, category: detector.category, state: "limited", enabled: true, emitted: 0, rejected: 1, duplicateCount: 0, capped: false, limitation: compact(`Detector input was malformed: ${error instanceof Error ? error.message : "unknown error"}`) }) }; }
  const seen = new Set<string>(); const drafts: DiagnosticDraft[] = []; let rejected = Math.max(0, runOutput.rejected); let duplicateCount = Math.max(0, runOutput.duplicateCount); const cap = Math.max(0, Math.min(detector.cap, Number.isFinite(availability.maxDiagnosticsPerDetector ?? detector.cap) ? Math.floor(availability.maxDiagnosticsPerDetector ?? detector.cap) : detector.cap)); let observed = 0;
  for (const candidate of runOutput.drafts) { const parsed = DiagnosticDraftSchema.safeParse(candidate); if (!parsed.success) { rejected++; continue; } const key = detector.dedupeKey(parsed.data); if (seen.has(key)) { duplicateCount++; continue; } seen.add(key); observed++; if (observed > cap) { rejected++; continue; } drafts.push(parsed.data); }
  const capped = observed > cap; const limitation = compact([inputState.reason, runOutput.limitation, runOutput.rejected > 0 ? "One or more supplied evidence observations were malformed and were excluded." : undefined, drafts.some((draft) => draft.state === "stale") ? "One or more observations are stale and remain limited to their captured evidence." : undefined, capped ? `Detector cap ${cap} was reached; ${observed - cap} additional observation(s) were retained in accounting.` : undefined].filter(Boolean).join(" ")) || undefined; const state = capped || limitation || inputState.state === "limited" ? "limited" : inputState.state === "unassessed" ? "unassessed" : "assessed";
  return { drafts, accounting: DetectorAccountingSchema.parse({ detectorId: detector.detectorId, detectorVersion: detector.detectorVersion, category: detector.category, state, enabled: true, emitted: drafts.length, rejected, duplicateCount, capped, ...(capped ? { cap: { limit: cap, observed, reason: limitation ?? "Detector cap was reached." } } : {}), ...(limitation ? { limitation } : {}) }) };
}

function probeLimitFor(context: DiagnosticContext): number { const value = context.probeBudget?.remaining; return Math.max(0, Number.isFinite(value) ? Math.floor(value!) : 8); }
function legacyEnabledFor(detectorId: string, availability: DiagnosticAvailability): boolean { return explicitlyEnabled(detectorId, availability).enabled; }
function legacyDisabledReason(detectorId: string, availability: DiagnosticAvailability): string | undefined { if (availability.disabledDetectorIds?.includes(detectorId)) return "Legacy detector was disabled for this run."; if (availability.enabledDetectorIds && !availability.enabledDetectorIds.includes(detectorId)) return "Legacy detector was not included in the enabled manifest."; if (detectorId === "broken-conversion-path" && availability.conversion === false) return "Conversion probes were disabled for this compatibility run."; if (detectorId === "broken-internal-link" && availability.internalLink === false) return "Internal-link probes were disabled for this compatibility run."; return undefined; }
function candidateToDraft(candidate: Candidate): DiagnosticDraft { const problemType = LEGACY_PROBLEM_TYPES[candidate.ruleId] ?? "broken_conversion_path"; const kind: "site" | "page" | "element" = candidate.ruleId === "no-service-pages" ? "site" : /#/.test(candidate.subject) ? "element" : "page"; const details = candidate.conversionDefect ? { kind: "conversion_defect" as const, conversionDefect: candidate.conversionDefect } : candidate.verification ? { kind: "verification" as const, verification: candidate.verification } : { kind: "legacy" as const, legacyRuleId: candidate.ruleId, ...(candidate.suppressedEvidenceRefs ? { suppressedEvidenceRefs: [...candidate.suppressedEvidenceRefs] } : {}) }; return DiagnosticDraftSchema.parse({ detectorId: candidate.ruleId, detectorVersion: "1", category: definitionForProblemType(problemType).category, problemType, subject: { kind, key: subjectKey(candidate.subject) }, observation: compact(sanitizeEvidenceText(candidate.detected), 4_900), legacyEvidenceRefs: unique(candidate.evidenceRefs), rawConfidence: candidate.rawConfidence, state: "observed", details, claimScope: "observed", counterEvidence: [], counterEvidenceState: "not_checked" }); }
async function runLegacyDiagnostics(context: DiagnosticContext): Promise<{ drafts: DiagnosticDraft[]; probeLimit: number; probeUsed: number; detectorDrafts: Map<string, DiagnosticDraft[]> }> { const candidates = await runRules(context); const drafts = candidates.map(candidateToDraft); const detectorDrafts = new Map<string, DiagnosticDraft[]>(); for (const detectorId of LEGACY_DETECTOR_IDS) detectorDrafts.set(detectorId, drafts.filter((draft) => draft.detectorId === detectorId)); return { drafts, probeLimit: probeLimitFor(context), probeUsed: 0, detectorDrafts }; }
function legacyInputState(detectorId: string, context: DiagnosticContext, availability: DiagnosticAvailability): AvailabilityState { const pageState = availabilityForKind(context, availability, "page"); if (pageState.state !== "assessed") return pageState; const readable = pagesOf(context).filter((page) => page.status >= 200 && page.status < 300 && page.wordCount > 0); if (!readable.length) return { state: "unassessed", reason: "No readable evidence pages were supplied to the legacy detector." }; if (["missing-meta-description", "missing-image-alt"].includes(detectorId)) { const field = detectorId === "missing-meta-description" ? "metaDescription" : "images"; if (readable.some((page) => !Object.prototype.hasOwnProperty.call(page, field))) return { state: "unassessed", reason: `${field} evidence was not supplied for every readable page.` }; } if ((detectorId === "missing-service-page" || detectorId === "no-service-pages") && !context.evidence.site.crawlExhaustive) return { state: "limited", reason: "The crawl was partial, so site-wide service absence is not assessed." }; return { state: "assessed" }; }
function legacyDetectorAccounting(detectorId: string, drafts: DiagnosticDraft[], enabled: boolean, inputState: AvailabilityState, disabledReason?: string): z.infer<typeof DetectorAccountingSchema> { const category = definitionForProblemType(LEGACY_PROBLEM_TYPES[detectorId]!).category; const state = !enabled ? "unavailable" : inputState.state !== "assessed" ? inputState.state : drafts.some((draft) => draft.state !== "observed") ? "limited" : "assessed"; return DetectorAccountingSchema.parse({ detectorId, detectorVersion: "1", category, state, enabled, emitted: enabled ? drafts.length : 0, rejected: 0, duplicateCount: 0, capped: false, ...(inputState.state !== "assessed" && enabled ? { limitation: inputState.reason } : {}), ...(!enabled ? { disabledReason: disabledReason ?? "Legacy detector was unavailable for this run." } : {}) }); }
function budget(limit: number, used: number, attempted = used, capped = false, capReason?: string) { const safeLimit = Math.max(0, Math.floor(limit)); const safeUsed = Math.max(0, Math.min(safeLimit, Math.floor(used))); return { limit: safeLimit, used: safeUsed, remaining: safeLimit - safeUsed, attempted: Math.max(safeUsed, Math.floor(attempted)), capped, ...(capped ? { capReason: capReason ?? "Budget was capped." } : {}) }; }
